function today(){return new Date().toISOString().slice(0,10)}
function filterTransactions(db,userId,u){let from=u.searchParams.get('from'),to=u.searchParams.get('to'),month=u.searchParams.get('month'),account=u.searchParams.get('account'),category=u.searchParams.get('category'),minAmount=u.searchParams.get('minAmount'),maxAmount=u.searchParams.get('maxAmount');if(!from&&!to){month=month||today().slice(0,7);from=month+'-01';to=month+'-31'}return db.transactions.filter(x=>x.userId===userId&&x.date>=from&&x.date<=(to||from)&&(!account||x.account===account)&&(!category||x.category===category)&&(!minAmount||x.amount>=Number(minAmount))&&(!maxAmount||x.amount<=Number(maxAmount))).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt-a.createdAt)}
function csvEscape(v){v=String(v??'');return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
function advanceRecurringTransactions(db,userId){let chains={};db.transactions.forEach(x=>{if(x.userId===userId&&x.recurrenceId)(chains[x.recurrenceId]=chains[x.recurrenceId]||[]).push(x)});let changed=false;for(const list of Object.values(chains)){let latest=list.sort((a,b)=>b.date.localeCompare(a.date))[0];if(!latest.recurrence)continue;let next=new Date(latest.date+'T12:00:00');if(latest.recurrence==='weekly')next.setDate(next.getDate()+7);else if(latest.recurrence==='monthly')next.setMonth(next.getMonth()+1);else next.setDate(next.getDate()+1);let nextDate=next.toISOString().slice(0,10);if(nextDate<=today()&&!list.some(x=>x.date===nextDate)){db.transactions.push({id:id(),userId,title:latest.title,amount:latest.amount,category:latest.category,kind:latest.kind,account:latest.account,date:nextDate,recurrence:latest.recurrence,recurrenceId:latest.recurrenceId,receipt:null,createdAt:Date.now()});changed=true}}return changed}
function enNum(v){return String(v).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d))}
function parseLifeText(text){let t=enNum(text),actions=[],m=t.match(/(?:خرید(?:م)?|خرج کردم|هزینه)[^\d]{0,25}(\d[\d,]*)/);if(m){let a=Number(m[1].replace(/,/g,''));actions.push({type:'transaction',amount:a,title:'هزینه ثبت‌شده از متن',category:/نان|رستوران|شام|غذا|کافه/.test(t)?'خوراک':'متفرقه'})}let w=t.match(/(\d+(?:\.\d+)?)\s*(?:ساعت|ساعتِ?)\s*(?:روی|کار)/);if(w)actions.push({type:'time',minutes:Math.round(Number(w[1])*60),title:'کار ثبت‌شده از متن'});let mood=t.match(/(?:حالم|مود)[^\d]{0,12}(\d{1,2})/);if(mood)actions.push({type:'mood',value:Math.min(10,Number(mood[1]))});let sleep=t.match(/(\d+(?:\.\d+)?)\s*ساعت\s*(?:خواب|خوابیدم)/);if(sleep)actions.push({type:'sleep',value:sleep[1]+' ساعت'});return actions}
