async function aiExtractActions(text){if(!AI_PROVIDER_API_KEY)return[];let sys='اعمال زیر را از متن فارسی کاربر استخراج کن و فقط یک آرایهٔ JSON برگردان، بدون هیچ توضیح اضافه. هر آیتم یکی از این ساختارهاست: {"type":"transaction","amount":عدد,"title":"...","category":"..."} یا {"type":"time","minutes":عدد,"title":"..."} یا {"type":"mood","value":عدد بین ۰ تا ۱۰} یا {"type":"sleep","value":"عدد ساعت"}. اگر چیزی برای استخراج نبود، آرایهٔ خالی [] برگردان.';try{let out=await aiComplete(sys,text,400);let m=out&&out.match(/\[[\s\S]*\]/);if(!m)return[];let arr=JSON.parse(m[0]);return Array.isArray(arr)?arr.filter(a=>a&&typeof a==='object'&&['transaction','time','mood','sleep'].includes(a.type)):[]}catch(e){return[]}}
function pearson(xs,ys){let n=xs.length;if(n<3)return null;let mx=xs.reduce((a,b)=>a+b,0)/n,my=ys.reduce((a,b)=>a+b,0)/n,num=0,dx2=0,dy2=0;for(let i=0;i<n;i++){let dx=xs[i]-mx,dy=ys[i]-my;num+=dx*dy;dx2+=dx*dx;dy2+=dy*dy}let den=Math.sqrt(dx2*dy2);return den===0?null:num/den}
